import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекст-агент', quota: 42, status: 'active' },
  { id: 'p2', name: 'Панель метрик', quota: 88, status: 'over' },
  { id: 'p3', name: 'Импорт данных', quota: 15, status: 'active' },
  { id: 'p4', name: 'Личный кабинет', quota: 100, status: 'over' },
  { id: 'p5', name: 'Мобильное приложение', quota: 60, status: 'paused' },
  { id: 'p6', name: 'Внутренний портал', quota: 5, status: 'paused' },
  { id: 'p7', name: 'Аналитика продаж', quota: 73, status: 'active' },
  { id: 'p8', name: 'Биллинг', quota: 30, status: 'active' },
  { id: 'p9', name: 'Служба поддержки', quota: 95, status: 'over' },
  { id: 'p10', name: 'Каталог товаров', quota: 20, status: 'paused' },
  { id: 'p11', name: 'Документация', quota: 50, status: 'active' },
  { id: 'p12', name: 'Тестовый стенд', quota: 8, status: 'active' },
];

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'Приостановлен',
  over: 'Превышен',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
};

const ALL_STATUSES: ProjectStatus[] = ['active', 'paused', 'over'];
const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const visible = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '480px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        padding: '20px',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {ALL_STATUSES.map((status) => (
          <JxChip
            key={status}
            active={activeStatuses.includes(status)}
            removable={activeStatuses.includes(status)}
            onClick={() => toggleStatus(status)}
            onRemove={() => toggleStatus(status)}
          >
            {STATUS_LABELS[status]}
          </JxChip>
        ))}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным фильтрам нет проектов."
          action={
            <JxButton variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <JxProgressCircle value={project.quota} showValue />
                <span
                  style={{
                    flex: 1,
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                  }}
                >
                  {project.name}
                </span>
                <JxBadge tone={STATUS_TONES[project.status]} dot>
                  {STATUS_LABELS[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

